namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.Add(new(_nextId++, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-10)));
        _notifications.Add(new(_nextId++, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-5)));
        _notifications.Add(new(_nextId++, "New feature: dark mode is available.", DateTime.UtcNow.AddMinutes(-1)));
    }

    /// <summary>Returns all notifications.</summary>
    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>Returns only notifications newer than the given id.</summary>
    public Task<List<Notification>> GetNotificationsSinceAsync(int lastSeenId)
    {
        lock (_lock)
        {
            return Task.FromResult(
                _notifications.Where(n => n.Id > lastSeenId).ToList());
        }
    }

    /// <summary>Simulates a new notification arriving. Called by background logic.</summary>
    public void SimulateIncoming()
    {
        string[] samples =
        [
            "You have a new follower.",
            "Someone commented on your post.",
            "Your build succeeded.",
            "Deployment complete.",
            "Disk usage above 80%.",
            "New sign-in from a new device.",
        ];

        lock (_lock)
        {
            var msg = samples[_nextId % samples.Length];
            _notifications.Add(new(_nextId++, msg, DateTime.UtcNow));
        }
    }
}

